INSERT INTO `tugas` (`id`, `guru_id`, `judul`, `deskripsi`, `deadline`, `kelas`, `created_at`, `updated_at`) VALUES ('1', '2', 'Tugas Bahasa Indonesia – Membuat Ringkasan Cerita', 'Bacalah cerpen pilihan pada bab 3 buku pelajaran Bahasa Indonesia, lalu buatlah ringkasan alur cerita beserta pesan moral dan nilai karakter yang terkandung di dalamnya.', '2026-10-18', 'VIII', '2026-09-16 02:02:12', NULL);
INSERT INTO `tugas` (`id`, `guru_id`, `judul`, `deskripsi`, `deadline`, `kelas`, `created_at`, `updated_at`) VALUES ('2', '2', 'Tugas Matematika – Latihan Soal Persamaan Linear', 'Kerjakan latihan soal tentang persamaan linear satu variabel pada halaman 10–15 di buku paket, kemudian unggah hasil pekerjaan dalam bentuk file PDF atau foto.', '2026-10-25', 'VIII', '2026-09-28 09:38:01', NULL);
INSERT INTO `tugas` (`id`, `guru_id`, `judul`, `deskripsi`, `deadline`, `kelas`, `created_at`, `updated_at`) VALUES ('3', '2', 'Tugas IPA – Laporan Praktikum Fotosintesis', 'Kerjakan dan susun laporan hasil praktikum fotosintesis menggunakan daun pacar air di laboratorium. Sertakan foto pengamatan dan kesimpulan.', '2026-10-22', 'VIII', '2026-09-28 09:38:01', NULL);
INSERT INTO `tugas` (`id`, `guru_id`, `judul`, `deskripsi`, `deadline`, `kelas`, `created_at`, `updated_at`) VALUES ('4', '2', 'Tugas Bahasa Inggris – Write a Short Paragraph', 'Write a short descriptive paragraph (5-8 sentences) about your favorite holiday destination or hobby using simple present tense and correct punctuation.', '2026-10-15', 'VIII', '2026-09-28 09:38:01', NULL);
INSERT INTO `tugas` (`id`, `guru_id`, `judul`, `deskripsi`, `deadline`, `kelas`, `created_at`, `updated_at`) VALUES ('5', '2', 'Tugas PPKn – Esai tentang Nilai-Nilai Pancasila', 'Tuliskan esai singkat mengenai pengamalan nilai-nilai luhur Pancasila sila kedua dan ketiga dalam kehidupan bermasyarakat dan di lingkungan sekolah.', '2026-10-10', 'VIII', '2026-09-28 09:38:01', NULL);

